import{_ as o,o as t,c as r,a3 as a}from"./chunks/framework.Ki30n65y.js";const n="/depgate/screenshots/monitoring.png",s="/depgate/screenshots/monitoring-report.png",i="/depgate/screenshots/monitoring-approve.png",l="/depgate/screenshots/monitoring-enforce.png",f=JSON.parse('{"title":"Monitor before enforcing","description":"","frontmatter":{},"headers":[],"relativePath":"admin/monitoring.md","filePath":"admin/monitoring.md"}'),p={name:"admin/monitoring.md"};function h(d,e,c,g,m,u){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="monitor-before-enforcing" tabindex="-1">Monitor before enforcing <a class="header-anchor" href="#monitor-before-enforcing" aria-label="Permalink to &quot;Monitor before enforcing&quot;">​</a></h1><p>A new policy that covers a whole ecosystem, such as &quot;approved licenses only&quot;, can break many builds the moment it is enforced. <strong>Monitor mode</strong> lets you see that impact first, on your real traffic, without blocking anything.</p><p>A Block policy in monitor mode records every download it <strong>would</strong> have blocked. The <strong>Monitoring</strong> page turns those records into an impact report: what would break, why, and how often. You then adjust the rule, approve the packages that must keep working, and enforce.</p><h2 id="the-rollout-in-five-steps" tabindex="-1">The rollout in five steps <a class="header-anchor" href="#the-rollout-in-five-steps" aria-label="Permalink to &quot;The rollout in five steps&quot;">​</a></h2><ol><li><strong>Create the policy in monitor mode.</strong> In the policy form, under <strong>Enforcement</strong>, choose <strong>Monitor only (log, don&#39;t block)</strong>. The summary reads <em>Would block …</em> instead of <em>Blocks …</em>.</li><li><strong>Let traffic flow.</strong> Leave it for long enough to cover your normal build cycle, typically one to two weeks.</li><li><strong>Review the report</strong> on the Monitoring page.</li><li><strong>Adjust.</strong> Narrow the rule with <strong>Edit rule</strong>, and <strong>Approve</strong> the packages that must keep working.</li><li><strong>Enforce.</strong> Review the final impact summary and confirm.</li></ol><p>Developers are not affected while a policy monitors. <a href="/depgate/developers/package-check">Package check</a> does tell them which versions will be blocked once the policy is enforced, so they can move early.</p><h2 id="the-monitoring-page" tabindex="-1">The Monitoring page <a class="header-anchor" href="#the-monitoring-page" aria-label="Permalink to &quot;The Monitoring page&quot;">​</a></h2><p>In the sidebar, choose <strong>Monitoring</strong>. The badge shows how many policies are monitoring.</p><p><img src="'+n+'" alt="The Monitoring page listing policies in monitor mode"></p><p>Each row shows the policy, when monitoring started, how many packages and downloads it recorded, how many packages <strong>will be blocked</strong> (recorded and not approved), how many are <strong>approved</strong>, and the last match. Sort by any column or search by name. <strong>Recently enforced</strong> lists policies enforced in the last 30 days, read-only.</p><h2 id="the-impact-report" tabindex="-1">The impact report <a class="header-anchor" href="#the-impact-report" aria-label="Permalink to &quot;The impact report&quot;">​</a></h2><p>Choose a policy to open its report.</p><p><img src="'+s+'" alt="The impact report for a license policy"></p><ul><li><strong>Totals</strong>: packages, downloads, packages that will be blocked, and approved packages.</li><li><strong>What it would block, by reason</strong>: one bar per reason, largest first. For a license policy, each license; for a vulnerability policy, each CVE; for a release type policy, each type. Choose a reason to filter the list.</li><li><strong>Packages</strong>: one line per package with its versions, the reason, downloads, last download and status. Expand a line to see each version. <strong>Also matched by</strong> lists other monitoring policies that recorded the same package.</li><li><strong>Filters</strong>: reason, ecosystem, repository, status and how recently the package was downloaded.</li><li><strong>Export</strong> downloads the list as CSV.</li></ul><p>Only real package downloads are recorded, and only when the policy would change the outcome: a version already blocked by another enforced policy, or allowed by a higher-priority Allow policy or an exception, is not recorded. Versions nobody has downloaded for 90 days drop out of the report.</p><h2 id="edit-the-rule" tabindex="-1">Edit the rule <a class="header-anchor" href="#edit-the-rule" aria-label="Permalink to &quot;Edit the rule&quot;">​</a></h2><p>Each reason has an <strong>Edit rule</strong> button. It opens the policy form with a suggested change already applied:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Suggestion</th></tr></thead><tbody><tr><td>License</td><td>Approve the license, unban it, or let packages without license information through.</td></tr><tr><td>Vulnerability</td><td>Remove the listed CVE, raise the CVSS minimum to the next rating, raise the EPSS threshold, or ignore unscored vulnerabilities.</td></tr><tr><td>Release type</td><td>Remove the type.</td></tr><tr><td>Release age</td><td>Halve the &quot;too new&quot; window, or double the &quot;unmaintained&quot; window.</td></tr><tr><td>Packages</td><td>Tells you which pattern to narrow.</td></tr></tbody></table><p>When you save a changed rule, DepGate rechecks everything recorded against the new rule and removes rows that no longer match. The page shows <strong>Rechecking…</strong> until it finishes.</p><h2 id="approve-packages" tabindex="-1">Approve packages <a class="header-anchor" href="#approve-packages" aria-label="Permalink to &quot;Approve packages&quot;">​</a></h2><p><strong>Approve</strong> lets a package keep working when the policy is enforced. Approve one package, one version from the expanded view, or several selected packages at once.</p><p><img src="'+i+'" alt="Approving a package"></p><ol><li>Choose which versions to approve: the versions downloaded, the range from lowest to highest downloaded version, or all versions including future ones.</li><li>Set <strong>Expires</strong> (90 days by default) and a <strong>Reason</strong>.</li><li>Choose <strong>Approve</strong>.</li></ol><p>An approval stops only <strong>this</strong> policy from matching the package. Every other policy and the malware list still apply. Vulnerability approvals always list versions, so a future vulnerable release is not let through. Release age and Release type policies offer no approvals: change the rule instead, or let developers request waivers.</p><p>Approvals appear under <strong>Approved packages</strong> in the policy, where you can revoke them.</p><h2 id="enforce" tabindex="-1">Enforce <a class="header-anchor" href="#enforce" aria-label="Permalink to &quot;Enforce&quot;">​</a></h2><p>Choose <strong>Enforce</strong> on the report or in the list. DepGate shows what enforcing will do: the packages and versions to be blocked, the downloads per day that would be refused, approved packages, the largest reasons, and how long the policy has been monitoring.</p><p><img src="'+l+'" alt="The Enforce confirmation"></p><p>Choose <strong>Enforce policy</strong> to confirm. Every DepGate replica applies it within seconds, and the change is recorded in the Audit Log. Packages nobody approved are now blocked; developers who need one can <a href="/depgate/developers/waiver-requests">request a waiver</a>.</p><p>To go back, edit the policy and choose <strong>Monitor only</strong> again. Monitoring then starts from an empty report.</p><h2 id="start-over" tabindex="-1">Start over <a class="header-anchor" href="#start-over" aria-label="Permalink to &quot;Start over&quot;">​</a></h2><p><strong>Restart monitoring</strong> (in the menu next to <strong>Enforce</strong>) clears every recorded row and resets <em>Monitoring since</em> to now, for example after a large change in your dependencies. Approvals are kept.</p>',32)])])}const w=o(p,[["render",h]]);export{f as __pageData,w as default};
